INSERT INTO `v1_9d28c6f94ebdb7468de0204a0871766344b075e1bbd0639e54d1768d32665041` VALUES (1, 66032, 11, 0, 1, "アオイさんですよね～っ！？\nグランドリームパークへようこそっ♪\n本日はおひとりさまですますか？", 10, 0, 0, 5146066, 130911);
