INSERT INTO `v1_9d28c6f94ebdb7468de0204a0871766344b075e1bbd0639e54d1768d32665041` VALUES (1, 66037, 11, 0, 1, "ぶひゃおおおお！？\nすすす、すみません！\nぼっちは強制退園ですよね！\n今すぐ出ていきますので～！", 15, 0, 0, 5146066, 104011);
